import{_ as o,o as a,c as t,a3 as r}from"./chunks/framework.WFmvnizL.js";const _=JSON.parse('{"title":"如何进行数据迁移、备份恢复？","description":"哪吒监控 V2 Dashboard 数据迁移、备份与恢复流程，说明停机、/opt/nezha 数据目录、权限、版本兼容和恢复验证注意事项。","frontmatter":{"description":"哪吒监控 V2 Dashboard 数据迁移、备份与恢复流程，说明停机、/opt/nezha 数据目录、权限、版本兼容和恢复验证注意事项。","outline":"deep"},"headers":[],"relativePath":"guide/q5.md","filePath":"guide/q5.md","lastUpdated":1785844584000}'),l={name:"guide/q5.md"};function s(d,e,i,n,c,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="如何进行数据迁移、备份恢复" tabindex="-1">如何进行数据迁移、备份恢复？ <a class="header-anchor" href="#如何进行数据迁移、备份恢复" aria-label="Permalink to &quot;如何进行数据迁移、备份恢复？&quot;">​</a></h1><p>按照以下步骤完成哪吒监控的数据迁移或备份恢复：</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>本页只适用于源端和目标端均为兼容 V2 版本的迁移或备份恢复。若数据来自 V0 或 V1，请先查看对应 Release 和迁移说明；不要假定跨产品代际可以通过直接覆盖文件完成升级。</p></div><ol><li><p><strong>停止面板服务</strong><br> 在旧服务器中运行一键脚本，选择 <code>停止面板</code>。</p></li><li><p><strong>备份数据</strong><br> 打包旧服务器中的 <code>/opt/nezha</code> 文件夹，并将其复制到新服务器相同位置。</p></li><li><p><strong>恢复数据</strong><br> 在新服务器中解压 <code>/opt/nezha</code> 文件夹至相同路径。</p></li><li><p><strong>启动面板服务</strong><br> 在新服务器中运行一键脚本，选择 <code>启动面板</code>。</p></li></ol><hr><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>确保 <code>/opt/nezha</code> 文件夹及其内容的权限和所有权在新服务器上正确设置。</li><li>数据迁移完成后，可以通过访问 Dashboard 界面验证迁移是否成功。</li></ul>',7)])])}const u=o(l,[["render",s]]);export{_ as __pageData,u as default};
